mapper.sql:
AND uid IN (
SELECT
    scoped_user.uid
FROM
    dm_auth_user scoped_user
LEFT JOIN
    dm_auth_user primary_user
ON
    primary_user.id = scoped_user.parent_id
WHERE
    scoped_user.uid  = #{puid}
    OR
    primary_user.uid = #{puid}
    )

        AND
        uid = #{uid}


         AND COALESCE(operate_time, gmt_create) >= #{dateStart} 


         AND COALESCE(operate_time, gmt_create) <= #{dateEnd} 


        AND
        status = #{status}


        AND
        requester = #{requester}


        AND
        ds_id = #{dsId}

mapper.select:
SELECT

FROM
    dm_exec_sql_audit
WHERE
    1 = 1

         AND id < #{startId} 


        AND
        uid = #{uid}


         AND gmt_create >= #{dateStart} 


         AND gmt_create <= #{dateEnd} 


        AND
        status = #{status}


        AND
        requester = #{requester}


        AND
        ds_id = #{dsId}

ORDER BY id DESC
LIMIT #{pageSize}

SELECT
FROM dm_exec_sql_audit WHERE 1 = 1
ORDER BY COALESCE(operate_time, gmt_create) DESC, id DESC LIMIT #{pageSize} OFFSET #{offset}
